3: // 三個型別簽名沿 Day 6 v1，不可改（specs/rules-v1.md）。
4: public record Order(bool Shipped, bool Paid, bool Cancelled);
5: public record CancellationResult(Order Order, bool RefundRequested);
6: 
7: public static class Cancellation
8: {
9:     // specs/rules-v2.md：BR-01 未出貨未取消可取消；BR-02 已出貨維持原訂單不丟例外；
10:     // BR-03（v2 改）已付款未出貨取消 → RefundRequested=true；BR-04（v2 新）已取消再取消 → 原狀、false、不丟例外。
11:     public static CancellationResult Cancel(Order order)
12:     {
13:         if (order.Shipped) return new CancellationResult(order, RefundRequested: false);   // BR-02
14:         if (order.Cancelled) return new CancellationResult(order, RefundRequested: false); // BR-04
15:         var cancelled = order with { Cancelled = true };                                    // BR-01
16:         return new CancellationResult(cancelled, RefundRequested: order.Paid);              // BR-03
17:     }
18: 
19:     /// 這次呼叫有沒有真的把狀態從未取消改成已取消（通知契約 NC-01 的分母）。
20:     public static bool Transitioned(Order before, CancellationResult after) => !before.Cancelled && after.Order.Cancelled;
21: }

